@startuml

class User {
  + ID : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class BusinessAccount extends Account {
  + companyName : string
  + monthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  + pageName : string
  + numberOfVisits : int
}

class AdvertisementPage extends Page {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

User "1" -- "1" Account
Account "1" -- "*" Page
PersonalAccount "1" -- "*" Page : has privilege
PersonalAccount "1" -- "*" PersonalAccount : friend request
BusinessAccount "1" -- "*" AdvertisementPage : creates

